import mx.eloeste.core.*;import org.json.*;
public final class UpdateManifestTests{
 static int checks;static JSONObject valid(){return new JSONObject().put("version","0.4.0").put("versionCode",5).put("bytes",16700000).put("sha256","a".repeat(64)).put("url","https://github.com/kingghhidorahx12/Estacionamiento-El-Oeste/releases/download/v0.4.0/El-Oeste-0.4.0-pruebas.apk");}
 static void rejects(JSONObject b){try{new UpdateManifest(b);throw new AssertionError("bad manifest accepted");}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args){new UpdateManifest(valid());checks++;rejects(valid().put("url","http://github.com/file.apk"));rejects(valid().put("url","https://example.com/update.apk"));rejects(valid().put("url","https://github.com/other/repo/releases/file.apk"));rejects(valid().put("version","../bad"));rejects(valid().put("versionCode",0));rejects(valid().put("bytes",UpdateManifest.MAX_BYTES+1));rejects(valid().put("sha256","bad"));for(String bad:new String[]{"http://github.com/x","https://github.com.attacker.example/x","https://user@github.com/x","https://127.0.0.1/x","https://github.com:444/x"}){if(UpdateManifest.downloadHost(bad))throw new AssertionError(bad);checks++;}if(!UpdateManifest.downloadHost("https://release-assets.githubusercontent.com/file?token=public-download"))throw new AssertionError();checks++;System.out.println("PASS · "+checks+" manifest and download channel checks.");}
}
